"""Contenders: sorting 10,000 seeded records by a key.

lambda key extraction vs operator.itemgetter.
"""

import operator
import random

N_RECORDS = 10_000
SEED = 42

_rng = random.Random(SEED)
RECORDS: list[dict] = [
    {"id": i, "score": _rng.random(), "name": f"rec-{i:05d}"}
    for i in range(N_RECORDS)
]

sort_by_lambda = lambda rows: sorted(rows, key=lambda r: r["score"])  # noqa: E731


def sort_by_itemgetter(rows: list[dict]) -> list[dict]:
    return sorted(rows, key=operator.itemgetter("score"))
